#!/usr/bin/env node
/**
 * Builds the pi-durable local worker host (src/local/main.ts) into one
 * self-contained ES module with esbuild — pi-durable, pi-ai and chord
 * inlined — and writes a content hash of the sources it was built from
 * beside it (tick 0ek, harness as a machine prerequisite).
 *
 * Run by `make harness-bundle` (and `make build`, which depends on it). The
 * output under embed/ is COMMITTED: go:embed (embedded.go, repository root)
 * needs it present with no build step, so a plain `go build`/`go test`
 * never has to run this script or install anything under harness/. Only
 * regenerating the bundle does.
 *
 * TestLocalHarnessBundleMatchesItsSources (internal/exec/subprocess) re-walks
 * the same sources in pure Go and fails the gate when the committed hash and
 * the tree disagree — so running this script and committing its output is
 * part of changing harness/src/local (or anything it imports) in this repo.
 */
import { build } from "esbuild";
import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const harnessRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = join(harnessRoot, "embed");
const outFile = join(outDir, "local-main.bundle.mjs");
const hashFile = join(outDir, "local-main.bundle.sources.sha256");

async function main() {
  await mkdir(outDir, { recursive: true });
  await build({
    entryPoints: [join(harnessRoot, "src", "local", "main.ts")],
    outfile: outFile,
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node22",
    legalComments: "none",
    // Read by src/local/main.ts's ensureDependencies: the bundle inlines
    // pi-durable, pi-ai and chord, so there is no node_modules to check for.
    define: { __TICFAC_HARNESS_BUNDLED__: "true" },
    banner: {
      js: "// GENERATED by harness/scripts/build-local-bundle.mjs from harness/src/local/main.ts — do not hand-edit, rerun the script instead.",
    },
  });
  const hash = await hashSources();
  await writeFile(hashFile, `${hash}\n`, "utf8");
  console.log(`wrote ${relative(harnessRoot, outFile)} and ${relative(harnessRoot, hashFile)} (sources ${hash})`);
}

/** Every file the bundle's sources hash covers, under harness/, sorted for a stable digest. */
async function sourceFiles() {
  const files = [];
  async function walk(dir) {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      if (entry.name === "node_modules") continue;
      const full = join(dir, entry.name);
      if (entry.isDirectory()) await walk(full);
      else files.push(full);
    }
  }
  await walk(join(harnessRoot, "src"));
  files.push(join(harnessRoot, "package.json"));
  files.push(join(harnessRoot, "pnpm-lock.yaml"));
  return files.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
}

/**
 * One digest over every source file's path and content: conservative rather
 * than precise. It covers the whole harness/src tree, not just main.ts's own
 * import graph, so an unrelated harness edit can call this "stale" when the
 * bundle itself would not change — a false positive the regenerate-and-commit
 * step always clears, and far cheaper than reproducing esbuild's own
 * dependency graph (its metafile) on the Go side of the gate.
 */
async function hashSources() {
  const digest = createHash("sha256");
  for (const file of await sourceFiles()) {
    digest.update(relative(harnessRoot, file).replaceAll("\\", "/"));
    digest.update("\0");
    digest.update(await readFile(file));
    digest.update("\0");
  }
  return digest.digest("hex");
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
